contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params specify amount to send and unlockTime to set
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // Read before values observable from c
        C.Holder memory before = c.Acc(address(this));
        uint beforeHolderBalance = before.balance;
        uint beforeContractBalance = address(c).balance;

        // Call Put with specified amount and unlockTime, sending Ether
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        C.Holder memory after = c.Acc(address(this));
        uint afterHolderBalance = after.balance;
        uint afterContractBalance = address(c).balance;

        // If the call succeeded (not reverted) then:
        //  - the holder balance must have increased exactly by amount
        //  - the contract's Ether balance must have increased exactly by amount
        // If the call reverted, state must be unchanged (balances equal to before)
        assert(
            (!reverted && afterHolderBalance == beforeHolderBalance + amount && afterContractBalance == beforeContractBalance + amount)
            || (reverted && afterHolderBalance == beforeHolderBalance && afterContractBalance == beforeContractBalance)
        );
    }

    // allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

