contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test tries to Collect a given amount; msg.sender for calls on c is this contract.
    // We require that this contract has previously deposited at least MinSum so Collect can potentially succeed.
    function run(uint depositAmount, uint collectAmount, uint unlockOffset) public payable {
        // ensure we can send depositAmount to c
        require(address(this).balance >= depositAmount);

        // initial observations
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // First deposit funds into c so that Acc[address(this)].balance increases and unlockTime can be set in future
        // Call Put with unlockTime = block.timestamp + unlockOffset to allow Collect only when block.timestamp > unlockTime
        // If deposit reverts we still proceed to attempt Collect to observe revert behaviour
        bool putReverted;
        try c.Put{value: depositAmount}(block.timestamp + unlockOffset) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read Acc after Put attempt
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Ensure we wait until unlock time by choosing collectOffset: we simulate by setting collectAmount and using the current block.timestamp condition implicitly.
        // Attempt to Collect collectAmount
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assertion: If Collect succeeded then contract balance decreased by exactly collectAmount and recorded balance decreased by exactly collectAmount.
        // If Collect reverted then both observed balances remain as they were before the Collect attempt (i.e., equal to mid values).
        assert(
            (collectReverted && afterBal == midBal && afterContractBal == midContractBal && afterUnlock == midUnlock)
            || (!collectReverted && afterBal + collectAmount == midBal && afterContractBal + collectAmount == midContractBal)
        );
    }

    // Allow receiving Ether when C sends funds to this test contract during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit funds via Put, then attempt Collect. Parameters:
    // depositAmt: amount to send to Put (must be available on this contract)
    // collectAmt: amount to attempt to Collect
    // unlockInFuture: if true, set unlockTime in future so Collect is expected to revert; if false set unlockTime = 0 so Collect can potentially succeed
    function run(uint depositAmt, uint collectAmt, bool unlockInFuture) public payable {
        require(address(this).balance >= depositAmt);

        // Observe initial Acc and contract balances for this test contract as caller of c
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put to deposit depositAmt into c for this contract's Acc entry.
        bool putReverted;
        uint unlockTime = unlockInFuture ? block.timestamp + 1000 : 0;
        try c.Put{value: depositAmt}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after Put attempt
        (uint midUnlock, uint midAccBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Attempt Collect of collectAmt (no ETH sent)
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect attempt
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assertion: Behavior must satisfy both parts:
        // 1) If Collect succeeded then both the stored Acc balance and contract balance decreased by exactly collectAmt.
        // 2) If Put succeeded then it did not reduce balances: mid balances are >= before balances and increased by at most depositAmt.
        assert(
            // Part A: Collect success implies exact decreases
            (
                !collectReverted && midAccBal >= collectAmt && afterAccBal + collectAmt == midAccBal && afterContractBal + collectAmt == midContractBal
            )
            // Part B: Collect reverted implies balances unchanged by Collect
            || (
                collectReverted && afterAccBal == midAccBal && afterContractBal == midContractBal
            )
        );

        // Separate invariant about Put: if Put succeeded then balances did not decrease
        assert(
            putReverted || (midAccBal >= beforeAccBal && midContractBal >= beforeContractBal)
        );
    }

    // receive to accept ETH from C during Collect
    receive() external payable {}
}

