contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put with an unlock time and an amount of wei to send.
    // Ensure this contract has enough balance before sending.
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);
        // Read balance for this test contract's holder before the Put
        (uint beforeBalance,) = getHolder();

        bool reverted;
        // call Put with value amount
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterBalance,) = getHolder();

        // If the call reverted, then recorded balance must be unchanged and contract balance unchanged.
        // If it did not revert, the recorded balance for this contract must have increased by exactly amount
        // and the contract's Ether balance must be >= amount bigger than before (we can observe address(c).balance only after the call,
        // but require the relation between before/after recorded balances).
        assert( reverted ? afterBalance == beforeBalance : afterBalance == beforeBalance + amount );
    }

    // helper to read the public mapping Acc for address(this) via its auto-generated getter
    function getHolder() internal returns (uint balance, uint unlockTime) {
        // C.Acc is a public mapping returning (Holder), so the getter has signature Acc(address) -> (uint unlockTime, uint balance)
        // but solidity returns tuple order as declared in struct. In contract C, struct Holder { uint unlockTime; uint balance; }
        // The auto getter will therefore return (uint,uint) in that order. We call it and reorder to (balance, unlockTime) for clarity.
        (uint u, uint b) = c.Acc(address(this));
        return (b, u);
    }

    // receive to accept Ether so this contract can forward it to c
    receive() external payable {}
}

