contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // allow receiving ETH so this contract can fund Put
    receive() external payable {}

    // single public function with all logic
    // params: initial deposit amount to Put, withdraw amount for Collect, and unlockTime to set (may be 0)
    function run(uint depositAmount, uint withdrawAmount, uint unlockTime) public payable {
        // ensure this test contract has enough ETH to fund Put
        require(address(this).balance >= depositAmount);

        // Read holder record before any operations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // First, try to Put depositAmount with given unlockTime
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after Put and before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect(withdrawAmount)
        bool collectReverted;
        try c.Collect{value: 0}(withdrawAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - If Collect did not revert, then recorded balance decreased by exactly withdrawAmount and contract balance decreased by at least withdrawAmount.
        // - If Collect reverted, then recorded balance and contract balance are unchanged from before the Collect call.
        // Note: we compare mid-state to after-state because Collect's effect is applied after Put.
        assert(!collectReverted
               ? afterBalance + withdrawAmount == midBalance && midContractBal >= afterContractBal && midContractBal - afterContractBal >= withdrawAmount
               : afterBalance == midBalance && afterContractBal == midContractBal);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // allow receiving ETH so this contract can be credited when Collect sends funds
    receive() external payable {}

    // single public test function
    // params: deposit amount to Put, withdraw amount for Collect, unlockTime for Put
    function run(uint depositAmount, uint withdrawAmount, uint unlockTime) public payable {
        // ensure this test contract has enough ETH to fund Put
        require(address(this).balance >= depositAmount);

        // observe holder record and contract balance before any operations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put (may revert)
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read mid-state after Put (or after failed Put)
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // attempt Collect
        bool collectReverted;
        try c.Collect{value: 0}(withdrawAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect reverted: nothing changed by Collect (balances equal to mid-state).
        // If Collect did not revert: either the recorded balance decreased by withdrawAmount and this contract's ETH balance increased by at least withdrawAmount,
        // OR nothing changed (Collect may be a no-op if preconditions failed silently). We assert one of these cases.
        assert(
            collectReverted
            ? (afterBalance == midBalance && afterContractBal == midContractBal)
            : (
                // successful Collect must not increase recorded balance
                (afterBalance + withdrawAmount == midBalance && afterContractBal >= midContractBal && afterContractBal - midContractBal >= withdrawAmount)
                || (afterBalance == midBalance && afterContractBal == midContractBal)
              )
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    // params: attempt to withdraw `withdrawAmount` (no deposit here), and a dummy value for unlockTime not used
    function run(uint withdrawAmount, uint dummyUnlock) public payable {
        // Observe holder record before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect; it may revert. We must not trigger sub_uint256 underflow inside C by causing Collect to succeed when _am>balance.
        // So we allow any withdrawAmount, but only assert a general property: after a non-reverting Collect, recorded balance is <= beforeBalance.
        bool collectReverted;
        try c.Collect{value: 0}(withdrawAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect (or after failed Collect)
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant: Collect cannot increase the recorded balance for this caller.
        // If Collect reverted, recorded balance must be unchanged. If it did not revert, recorded balance must be <= beforeBalance.
        assert(collectReverted ? (afterBalance == beforeBalance && afterContractBal == beforeContractBal) : (afterBalance <= beforeBalance));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some funds via Put, then attempt Collect of amount am.
    // Parameters: unlockTime for Put, deposit amount dep, collect amount am.
    function run(uint unlockTime, uint dep, uint am) public payable {
        require(address(this).balance >= dep, "insufficient test balance");
        // Ensure MinSum condition potentially satisfied by depositing dep
        // Call Put sending dep wei
        c.Put{value: dep}(unlockTime);

        // Read before-values: contract Ether balance and recorded per-address balance
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));

        // Try Collect and capture whether it reverted
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        (, uint afterAccBal) = c.Acc(address(this));

        // If Collect did not revert then the contract balance must have decreased by am
        // and the recorded account balance must also have decreased by am.
        // If it reverted, we make no claim.
        assert(reverted || (beforeContractBal == afterContractBal + am && beforeAccBal == afterAccBal + am));
    }

    receive() external payable {}
}

